namespace Talabat.Domain.Interfaces;

public interface IUnitOfWork
{
    Task<int> SaveChangesAsync(CancellationToken cancellationToken = default);

    /// <summary>
    /// Runs <paramref name="operation"/> atomically: every save performed inside it commits
    /// together, or none does if the operation throws. Use it when one use case must persist
    /// several aggregates and a later save depends on an id generated by an earlier one.
    /// </summary>
    Task ExecuteInTransactionAsync(
        Func<CancellationToken, Task> operation,
        CancellationToken cancellationToken = default);
}
